<script setup lang="ts">definePageMeta({layout:'admin',middleware:'admin'});const {data}=await useFetch('/api/admin/posts');const timestamp=(value:string)=>`${new Date(value).toISOString().slice(0,16).replace('T',' ')} UTC`</script><template><div><div class="flex justify-between"><h1 class="text-3xl font-semibold">文章</h1><NuxtLink to="/admin/posts/new" class="rounded-full px-5 py-2 text-white" style="background:var(--accent)">新建文章</NuxtLink></div><div class="mt-8 border-t" style="border-color:var(--border)"><NuxtLink v-for="p in data||[]" :key="p.id" :to="`/admin/posts/${p.id}`" class="grid grid-cols-[1fr_auto] gap-4 border-b py-5" style="border-color:var(--border)"><div><h2 class="font-semibold">{{p.title}}</h2><p class="text-sm" style="color:var(--muted)">/{{p.slug}} · {{timestamp(p.updatedAt)}}</p></div><span class="text-sm">{{p.status}}</span></NuxtLink></div></div></template>
